mapper.select:
SELECT id, ds_id, session_id, question, generated_sql, modified_sql, change_type,
       feedback_type, user_comment, review_conclusion, status, create_time, update_time
FROM kb_feedback
WHERE ds_id = #{dsId}

    AND status = #{status}


    AND session_id = #{sessionId}


    AND create_time >= #{startTime}


    AND create_time <= #{endTime}

ORDER BY create_time DESC
